  &reftitle.examples;

   stream_bucket_append example


<?php
class upper_filter extends php_user_filter
{
    public function filter($in, $out, &$consumed, bool $closing): int
    {
        while ($bucket = stream_bucket_make_writeable($in)) {
            $bucket->data = strtoupper($bucket->data);
            $consumed += $bucket->dataLength;
            stream_bucket_append($out, $bucket);
        }

        return PSFS_PASS_ON;
    }
}

stream_filter_register('upper', 'upper_filter');

$stream = fopen('php://memory', 'w+');
stream_filter_append($stream, 'upper', STREAM_FILTER_WRITE);
fwrite($stream, "hello\n");
rewind($stream);
echo stream_get_contents($stream);


   &example.outputs;


HELLO
